 * The scanner. It turns UTF-8 source text into positioned tokens, following the
 * language rules: whitespace and comments separate tokens, identifiers and
 * keywords, numbers with prefixes and separators, strings with escapes, raw
 * strings, and a fixed punctuation table matched longest first.
 */

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

/** The punctuation, longest first so that `==` beats `=`. */
const PUNCT = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

/** A scan failure, carrying the position it is reported at and its reason. */
export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.name = 'ScanError'
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => isDigit(c) || (c !== undefined && ((c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')))
const isBin = (c) => c === '0' || c === '1'
const isOctal = (c) => c !== undefined && c >= '0' && c <= '7'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentPart = (c) => isIdentStart(c) || isDigit(c)

/**
 * Scans the whole source and returns its tokens. Throws a ScanError at the
 * first failure.
 */
export function scan(source) {
  return new Scanner(source).run()
}

class Scanner {
  constructor(source) {
    /** The source as code points, so that columns count code points. */
    this.chars = Array.from(source)
    this.index = 0
    this.line = 1
    this.column = 1
  }

  /** The code point `offset` positions ahead, or undefined past the end. */
  peek(offset = 0) {
    return this.chars[this.index + offset]
  }

  atEnd() {
    return this.index >= this.chars.length
  }

  /** Reads one code point, moving the position the way the rules say. */
  advance() {
    const c = this.chars[this.index++]
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column += 4 - ((this.column - 1) % 4)
    } else {
      this.column += 1
    }
    return c
  }

  /** The source text between two indexes. */
  slice(from, to) {
    return this.chars.slice(from, to).join('')
  }

  run() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.atEnd()) return tokens
      tokens.push(this.scanToken())
    }
  }

  /** Skips spaces, carriage returns, line feeds, tabs and both comments. */
  skipTrivia() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      return
    }
  }

  /** Skips a block comment, which nests, and reports it at its outermost `/*`. */
  skipBlockComment() {
    const line = this.line
    const column = this.column
    this.advance()
    this.advance()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth += 1
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth -= 1
      } else {
        this.advance()
      }
    }
  }

  scanToken() {
    const line = this.line
    const column = this.column
    const c = this.peek()

    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(line, column)
    if (isIdentStart(c)) return this.scanIdentifier(line, column)
    if (isDigit(c)) return this.scanNumber(line, column)
    if (c === '"') return this.scanString(line, column)

    for (const punct of PUNCT) {
      if (this.matches(punct)) {
        for (let i = 0; i < punct.length; i += 1) this.advance()
        return { kind: 'punct', line, column, text: punct, value: punct }
      }
    }

    throw new ScanError(line, column, `unexpected character ${c}`)
  }

  matches(text) {
    for (let i = 0; i < text.length; i += 1) {
      if (this.peek(i) !== text[i]) return false
    }
    return true
  }

  scanIdentifier(line, column) {
    const start = this.index
    while (isIdentPart(this.peek())) this.advance()
    const text = this.slice(start, this.index)
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line, column, text, value: text }
  }

  /** Consumes a run of digits, allowing `_` only between two of them. */
  consumeDigits(isPart) {
    let count = 0
