      this.advance()
      count += 1
      if (this.peek() === '_' && isPart(this.peek(1))) this.advance()
    }
    return count
  }

  scanNumber(line, column) {
    const start = this.index
    let ok = true

    if (this.peek() === '0' && 'xXbBoO'.includes(this.peek(1) ?? '')) {
      const marker = this.peek(1)
