      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        const signed = this.peek(1) === '+' || this.peek(1) === '-'
        if (isDigit(this.peek(1)) || (signed && isDigit(this.peek(2)))) {
          this.advance()
          if (signed) this.advance()
          this.consumeDigits(isDigit)
        }
      }
    }

    // Anything word-like left glued to the number belongs to the reported text.
    if (isIdentPart(this.peek())) {
      ok = false
      while (isIdentPart(this.peek())) this.advance()
    }

    const text = this.slice(start, this.index)
    if (!ok) throw new ScanError(line, column, `invalid number ${text}`)
    return { kind: 'number', line, column, text, value: text }
  }

  scanString(line, column) {
    const start = this.index
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated string')
      const c = this.peek()
      if (c === '\n') throw new ScanError(this.line, this.column, 'newline in string')
      if (c === '"') {
        this.advance()
        const text = this.slice(start, this.index)
        return { kind: 'string', line, column, text, value }
      }
      if (c === '\\') {
        value += this.scanEscape()
        continue
      }
      value += this.advance()
    }
  }

  /** Reads one escape and returns what it stands for. */
  scanEscape() {
    const line = this.line
    const column = this.column
    this.advance()
    if (this.atEnd()) throw new ScanError(line, column, 'invalid escape \\')
    const c = this.advance()
    const bad = () => new ScanError(line, column, `invalid escape \\${c}`)
    switch (c) {
      case 'n': return '\n'
      case 't': return '\t'
      case 'r': return '\r'
      case '\\': return '\\'
      case '"': return '"'
      case '0': return '\0'
      case 'x': {
        if (!isHex(this.peek()) || !isHex(this.peek(1))) throw bad()
        const hex = this.advance() + this.advance()
        return String.fromCharCode(parseInt(hex, 16))
      }
      case 'u': {
        if (this.peek() !== '{') throw bad()
        let digits = ''
        let offset = 1
        while (isHex(this.peek(offset))) {
          digits += this.peek(offset)
          offset += 1
        }
        if (digits.length === 0 || this.peek(offset) !== '}') throw bad()
        const code = parseInt(digits, 16)
        if (code > 0x10ffff) throw bad()
        for (let i = 0; i <= offset; i += 1) this.advance()
        return String.fromCodePoint(code)
      }
      default:
        throw bad()
    }
  }

  scanRawString(line, column) {
    const start = this.index
    this.advance()
    this.advance()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated string')
      const c = this.advance()
      if (c === '"') {
        const text = this.slice(start, this.index)
        return { kind: 'rawstring', line, column, text, value }
      }
      value += c
    }
  }
}
