/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError, KINDS } from './scanner.js'

/** Reads the whole of standard input as UTF-8, treating a closed one as empty. */
function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** One line per token: position, kind, and body. */
function renderTokens(tokens) {
  let out = ''
  for (const token of tokens) {
    const body = token.kind === 'string' || token.kind === 'rawstring'
      ? JSON.stringify(token.value)
      : token.text
    out += `${token.line}:${token.column} ${token.kind} ${body}\n`
  }
  return out
}

/** One line per kind, every kind listed, then the total. */
function renderStats(tokens) {
  const counts = new Map(KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)
  let out = ''
  for (const kind of KINDS) out += `${kind} ${counts.get(kind)}\n`
  return out + `total ${tokens.length}\n`
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : undefined
  if (mode !== 'tokens' && mode !== 'stats') fail('usage: cli.js tokens|stats')

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (error instanceof ScanError) fail(error.message)
    throw error
  }

  process.stdout.write(mode === 'tokens' ? renderTokens(tokens) : renderStats(tokens))
}

main()
